import java.util.*;

public class Ex12 {
    static class Config { String appName; int port; }
    public static void main(String[] args) {
        // 模拟 @PropertySource 加载的外部配置
        Map<String,String> props = Map.of("app.name","CppMind","app.port","8080");
        Config cfg = new Config();
        // 容器按字段名把占位符值反射注入
        cfg.appName = props.get("app.name");
        cfg.port = Integer.parseInt(props.get("app.port"));
        System.out.println("appName=" + cfg.appName);
        System.out.println("port=" + cfg.port);
    }
}
